private.reauthentication_required(text):
CREATE OR REPLACE FUNCTION private.reauthentication_required(p_scope text)
 RETURNS boolean
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$
declare required boolean;
begin
 if p_scope='employee_bank_registration' then return private.employee_bank_initial_enabled();end if;
 select enabled into required from private.reauthentication_rollout where scope=p_scope for share;
 if not found then raise sqlstate '42501' using message='reauthentication_unavailable'; end if;
 return required;
end $function$

public.issue_reauthentication_proof(uuid:
CREATE OR REPLACE FUNCTION public.issue_reauthentication_proof(p_actor uuid, p_session uuid, p_operation text, p_target jsonb, p_proof_hash text)
 RETURNS timestamp with time zone
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO ''
AS $function$declare expiry timestamptz;
begin
 if coalesce(auth.role(),'')<>'service_role' or p_operation in('secondary_password.change','attendance.manage') then
  raise sqlstate '42501' using message='reauthentication_unavailable';end if;
 -- Shared issuer establishes genuine actor/live original SID and one ledger
 -- entry first. A later bank target/permission failure rolls back that entry.
 expiry:=private.issue_reauthentication_proof(p_actor,p_session,p_operation,p_target,p_proof_hash);
 if p_operation='employee.bank.initial' then perform private.employee_bank_initial_issue_target(p_actor,p_target);end if;
 return expiry;
end $function$
